for(const name of ['AudioRuntimeConfig.js','AudioRuntimeObservation.js','AudioRuntimeTransition.js','browserNotePreview.js']){const filename='js/app/midi-ui/'+name,source=execFileSync('git',['show',parent+':'+filename],{encoding:'utf8'}),url=new URL(name,base),tree=ts.createSourceFile(name,source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS),edits=[];const literal=node=>{if(node&&ts.isStringLiteralLike(node)&&node.text.startsWith('.')){const target=new URL(node.text,url).href;edits.push({start:node.getStart(tree),end:node.end,text:JSON.stringify(resolved.get(target)||target)});}};const visit=node=>{if((ts.isImportDeclaration(node)||ts.isExportDeclaration(node))&&node.moduleSpecifier)literal(node.moduleSpecifier);if(ts.isCallExpression(node)&&node.expression.kind===ts.SyntaxKind.ImportKeyword)literal(node.arguments[0]);if(ts.isNewExpression(node)&&ts.isIdentifier(node.expression)&&node.expression.text==='URL'&&ts.isStringLiteralLike(node.arguments?.[0])&&!node.arguments[0].text.endsWith('/'))literal(node.arguments[0]);ts.forEachChild(node,visit);};visit(tree);assert.equal(edits.length,discoverRuntimeDependencies(name,source).filter(s=>s.startsWith('.')).length);let normalized=source;for(const edit of edits.sort((a,b)=>b.start-a.start))normalized=normalized.slice(0,edit.start)+edit.text+normalized.slice(edit.end);resolved.set(url.href,'data:text/javascript;base64,'+Buffer.from(normalized).toString('base64'));sources.push({path:filename,sha256:createHash('sha256').update(source).digest('hex'),normalizedLiteralCount:edits.length});}
